    const pillsOf = [...f.html.matchAll(/<g data-el="set:[^"]*" style="cursor:pointer"><title>[^<]*<\/title><rect x="([\d.-]+)" y="([\d.-]+)" width="([\d.]+)" height="([\d.]+)"/g)].map((m) => ({ id: 'pill', x: +m[1], y: +m[2], w: +m[3], h: +m[4] }));
